    {
      "path": "cordis.patch.yml",
      "content": "# One row, named exactly like the package: dsh-client-modules mounts a package's\n# browser half on the row whose specifier is the package name, so this row also\n# carries the Plugins-page configuration for every feature.\n#\n# Each section owns its enable switch and only the keys that feature reads. The\n# data capture and the TUI integration stay off by default. Legacy component modules (mode-*, discovery, panel, tui, shell,\n# file, ptc, hide-official, background) remain exported: a saved override for one\n# of those specifiers still loads its legacy module, it just cannot match this row.\n- insert:\n    - id: dsh-ops\n      name: dsh-ops\n      config:\n        # Four bundle switches (one per preset switch), then each preset; all default on.\n        global:\n          bash: true\n          hidePwsh: true\n          hideOfficialTools: true\n          dynamicTools: true\n        minimal:\n          enabled: true\n        standard:\n          enabled: true\n          residentTools: true\n        ptc:\n          enabled: true\n          residentTools: true\n        cordis:\n          enabled: true\n          residentTools: true\n        discovery:\n          enabled: true\n        panel:\n          enabled: false\n        tui:\n          enabled: false\n"
    },
    {
      "path": "src/index.ts",
      "content": "/** Single-row composition root. All presets consume the same assembly pipeline. */\nimport type { Context } from './adapter/dsh/types.js'\nimport { applyResolvedMode } from './presets/builtin.js'\nimport { resolveModeConfig } from './presets/config.js'\nimport { resolveMergedConfig, effectiveMode, dynamicForMode } from './settings/merged.js'\nimport { beginMergedRow, endMergedRow } from './settings/legacy.js'\nimport { mountIntegration } from './integration/index.js'\nimport { gateConsumer } from './consumer/gates.js'\nimport { resolveIntegrationConfig } from './consumer/options.js'\nimport { mountRuntimeSettings } from './settings/runtime-host.js'\nimport { companionVersion } from './settings/companion.js'\nimport * as panelModule from './components/panel/index.js'\nimport * as tuiModule from './components/tui/index.js'\nexport { Config } from './settings/merged.js'\nexport { applyComponent } from './legacy/host.js'\nexport const name = 'dsh-ops'\n\n/**\n * Package-root entry: the single row the bundle inserts.\n *\n * Every feature the row enables is mounted from this one fiber with its own\n * validated slice. Disabling a feature and saving the row remounts the fiber, so\n * its effects are torn down exactly like the old per-row switches did. The TUI\n * link keeps its optional host service: an absent `tuiPanels` leaves that\n * desktop feature pending instead of blocking the tools.\n */\n\nexport async function apply(root: Context, rawConfig: unknown): Promise<void> {\n  const config = resolveMergedConfig(rawConfig)\n  const host = root\n  const mount = async (module: { apply(...args: unknown[]): unknown }, state: { enabled: boolean; raw?: Record<string, unknown>; config: unknown }, slice?: Record<string, unknown>): Promise<void> => {\n    if (!state.enabled) return\n    const payload = slice ?? state.raw ?? state.config\n    if (state.raw === undefined && slice === undefined) {\n      await host.plugin({ name: `dsh-ops/${moduleName(module)}`, apply: (ctx: Context) => { (module.apply as (ctx: Context, config: unknown) => void)(ctx, state.config) } })\n      return\n    }\n    await host.plugin(module, payload)\n  }\n  beginMergedRow()\n  try {\n    // The browser half mounts its `opsSettings` remote; the legacy shell row used\n    // to provide that seam, so the merged row owns it now.\n    await host.plugin({ name: 'dsh-ops/runtime-settings', apply: (ctx: Context) => mountRuntimeSettings(ctx) })\n    for (const mode of ['minimal', 'standard', 'ptc', 'cordis'] as const) {\n      const state = config[mode]\n      const effective = resolveModeConfig(effectiveMode(state, config.global, typeof config.other.raw?.pwsh7Link === 'boolean' ? config.other.raw.pwsh7Link : companionVersion({ sweep: false }) !== undefined), mode)\n      await host.plugin({ name: `dsh-ops/consumer-${mode}`, apply(ctx: Context) {\n        applyResolvedMode(ctx, effective, mode, { enabled: state.enabled,\n          discovery: { ...config.discovery.config, enabled: config.discovery.enabled },\n          dynamic: dynamicForMode(state, config.global) })\n      } })\n    }\n    for (const row of Object.values(config.presets)) {\n      const options = row.options\n      const resolved = resolveIntegrationConfig(options)\n      const linked = typeof config.other.raw?.pwsh7Link === 'boolean' ? config.other.raw.pwsh7Link : companionVersion({ sweep: false }) !== undefined\n      const effective = gateConsumer(resolved, config.global, linked)\n      await host.plugin({ name: `dsh-ops/custom-${resolved.preset}`, apply(ctx: Context) { return mountIntegration(ctx, effective) } })\n    }\n    await mount(panelModule, config.panel)\n    await mount(tuiModule, config.tui)\n  } finally { endMergedRow() }\n}\n\n/** The module's declared name, for the child plugin label. */\nfunction moduleName(module: unknown): string {\n  const value = (module as { name?: unknown }).name\n  return typeof value === 'string' ? value : 'feature'\n}\n"
    },
    {
      "path": "src/presets/defaults.ts",
      "content": "/**\n * What each mode contributes to a session of its preset.\n *\n * This table is the product contract between the four mode rows and the shared\n * publication controllers: resident OPS tools, official tools replaced once\n * their OPS counterpart is visible, and whether the mode consumes the advanced\n * file tools through the discovery entry.\n */\nimport type { OfficialReplacement } from '../capabilities/replacements.js'\nimport { publicToolName } from '../policy.js'\nimport type { ModeId } from './types.js'\n\nimport { NATIVE_RESIDENT_RAW, SHELL_OFFICIAL_NAMES } from '../capabilities/profiles.js'\nexport { NATIVE_RESIDENT_RAW, SHELL_OFFICIAL_NAMES } from '../capabilities/profiles.js'\n\n/** One mode's publication and replacement policy. */\nexport interface ModePlan {\n  /** Publish the resident native file tools for matching Agents. */\n  nativeFiles: boolean\n  /** Official file tools replaced once their OPS counterpart is visible in the same scope. */\n  replacements: readonly OfficialReplacement[]\n  /** Replace the official Windows shell with ops_bash when the row is on. */\n  shell: boolean\n  /** Publish the PTC SDK APIs for matching Agents. */\n  ptc: boolean\n  /** Progressive discovery population for matching Agents. */\n  discovery: 'none' | 'advanced' | 'all'\n  /** The mode's routing section suffix; null publishes no routing text. */\n  section: string | null\n}\n\nconst NATIVE_REPLACEMENTS: readonly OfficialReplacement[] = Object.freeze(['read', 'glob', 'grep'])\n\n/** Everything one mode publishes; consumers read this instead of branching on ids. */\nexport const MODE_PLANS: Readonly<Record<ModeId, ModePlan>> = Object.freeze({\n  // Minimal keeps its terse prompts: only the Windows shell is replaced, and\n  // advanced tools arrive through the discovery entry when that row is on.\n  minimal: Object.freeze({ nativeFiles: false, replacements: [], shell: true, ptc: false, discovery: 'all', section: null }),\n  standard: Object.freeze({ nativeFiles: true, replacements: NATIVE_REPLACEMENTS, shell: true, ptc: false, discovery: 'advanced', section: 'standard' }),\n  ptc: Object.freeze({ nativeFiles: false, replacements: [], shell: true, ptc: true, discovery: 'none', section: 'ptc' }),\n  cordis: Object.freeze({ nativeFiles: true, replacements: NATIVE_REPLACEMENTS, shell: true, ptc: false, discovery: 'advanced', section: 'cordis' }),\n})\n\n/**\n * The resident native capability names of one mode.\n * @param mode - the mode to read.\n * @returns public OPS names, or an empty list when the mode publishes no native file tools.\n */\nexport function residentTools(mode: ModeId): readonly string[] {\n  return MODE_PLANS[mode].nativeFiles ? NATIVE_RESIDENT_RAW.map(raw => publicToolName(raw)) : []\n}\n"
    },
    {
      "path": "src/consumer/mount.ts",
      "content": "/** One assembly path: consumers supply policy, publishers own registration and execution. */\nimport type { Context } from '../adapter/dsh/types.js'\nimport { resolveShells } from '../shells.js'\nimport { mountSessionBash } from '../session-shells.js'\nimport { mountWorkspacePreparation } from '../workspace-preparation.js'\nimport { mountNative } from '../publication/native.js'\nimport { mountReplacements } from '../publication/replacements.js'\nimport { mountDiscovery } from '../discovery/controller.js'\nimport { mountPtc } from '../publication/ptc.js'\nimport { NATIVE_RESIDENT_RAW } from '../capabilities/profiles.js'\nimport { BASH_TOOL, publicToolName, renderToolingPolicy, TOOLING_SECTION } from '../policy.js'\nimport type { ConsumerPlan } from './types.js'\n\nexport function mountConsumer(ctx: Context, plan: ConsumerPlan): void {\n  const { gate, core } = plan\n  if (plan.shell) {\n    if (process.platform === 'win32') mountWorkspacePreparation(ctx)\n    const shells = resolveShells(core)\n    ctx.inject(['tools'], inner => mountSessionBash(inner, core, shells, gate))\n    if (core.promptPolicy && (!plan.files || !plan.residentTools)) ctx.inject(['tools', 'systemPrompt'], inner => {\n      inner.effect(() => inner.systemPrompt.section({ name: `${TOOLING_SECTION}:consumer-shell-${plan.id}`, order: 3254, interpolate: false,\n        text: context => {\n          const agent = context.agent ?? context.scope as Parameters<typeof gate.allows>[0]\n          return agent && gate.allows(agent) ? renderToolingPolicy({ published: inner.get('tools')?.get(BASH_TOOL, agent) ? [BASH_TOOL] : [], extraGuidance: core.extraGuidance }) : ''\n        } }), 'dsh-ops: consumer shell guidance')\n    })\n  }\n  if (plan.presentation === 'native') {\n    const residents = plan.files && plan.residentTools ? (plan.residentNames ?? NATIVE_RESIDENT_RAW) : []\n    if (residents.length) mountNative(ctx, core, { id: plan.id, tools: residents, section: plan.section, gate })\n    if (plan.discovery || plan.native.alwaysLoaded.length || plan.external.allowed.length) mountDiscovery(ctx,\n      { ...plan.native, enabled: plan.discovery }, { ...gate, guidance: core.promptPolicy, extraGuidance: core.extraGuidance,\n        residentTools: () => residents.map(publicToolName), external: plan.external })\n  } else if (plan.files) mountPtc(ctx, plan.ptc, { ...gate, guidance: core.promptPolicy, resident: plan.residentTools, dynamic: plan.discovery })\n  if (plan.replaceOfficial) mountReplacements(ctx, { id: plan.id, targets: plan.replacementTargets, gate, keepOfficial: () => false })\n}\n"
    },
    {
      "path": "src/publication/native.ts",
      "content": "/** Scoped Native file publication. Callers supply policy; this controller owns lifecycle. */\nimport type { Context, Fiber } from '../adapter/dsh/types.js'\nimport type { Agent } from '../adapter/dsh/types.js'\nimport type {} from '../adapter/dsh/types.js'\nimport { NativeFileTools } from '../projections/native/runtime.js'\nimport { registerNativeProviderAtScope } from './providers.js'\nimport { resolveWorker } from '../execution/files.js'\nimport { mountResultLifecycle } from '../kernel/result-lifecycle.js'\nimport { BASH_TOOL, modeSectionName, MODE_SECTION_ORDERS, renderToolingPolicy } from '../policy.js'\nimport { visibleNames } from './surface.js'\nimport { isNativePresentation, isPresentationProbe } from './presentation.js'\nimport { onToolChange } from './changes.js'\nimport type { ResolvedConfig } from '../config.js'\nimport { ownScopes } from './ownership.js'\nimport { failure } from '../execution/files.js'\nimport type { PublicationGate } from './types.js'\n\ntype ResidentName = Parameters<NativeFileTools['definition']>[0]\n\ninterface Entry {\n  agent: Agent\n  ctx?: Context\n  fiber?: Fiber\n  runtime: NativeFileTools\n  owned: Set<string>\n  disposers: (() => void)[]\n  ready: Promise<void>\n}\n\n/** The names, guidance and eligibility supplied by one composition. */\nexport interface NativePublication {\n  id: string\n  tools: readonly ResidentName[]\n  section: string | null\n  gate: PublicationGate\n}\n\nexport function mountNative(root: Context, config: ResolvedConfig, publication: NativePublication): void {\n  const { id: mode, tools: names, section, gate } = publication\n  let worker: string\n  try { worker = resolveWorker({ binaryPath: config.binaryPath }) } catch (error) {\n    if (config.required) throw error\n    root.logger.warn(`dsh-ops: ${mode} mode cannot resolve its native worker; native file tools stay unpublished. ${String((error as Error)?.message ?? error)}`)\n    return\n  }\n  root.inject(['tools', 'systemPrompt', 'sandboxPolicy', 'subprocess'], async ctx => {\n    const tools = ctx.get('tools')\n    const prompt = ctx.get('systemPrompt')\n    if (!tools || !prompt) return\n    mountResultLifecycle(ctx)\n    const entries = new Map<Agent, Entry>()\n    let stopped = false, mutating = false\n    const ownership = await ownScopes(ctx, 'native-files', () => reconcile(), gate.allows)\n    const native = new Map<Agent, boolean>()\n    const clear = (entry: Entry): void => {\n      entry.owned.clear()\n      for (const dispose of entry.disposers.splice(0)) {\n        try { dispose() } catch (error) { ctx.logger.warn(`dsh-ops: ${mode} native publication cleanup failed: ${String(error)}`) }\n      }\n      entry.runtime.cancel('Mode row ownership changed')\n      void entry.runtime.stop().catch(error => ctx.logger.warn(`dsh-ops: ${mode} native runtime stop failed: ${String(error)}`))\n    }\n    const publish = (agent: Agent, entry: Entry): void => {\n      if (!entry.ctx) return\n      const scope = agent\n      const definitions = names.map(name => {\n        const definition = entry.runtime.definition(name)\n        return { ...definition, execute: async (args: unknown, exec: Parameters<typeof definition.execute>[1]) => {\n          if (stopped || entries.get(agent) !== entry || !cover(agent) || exec.agent !== agent\n            || !await isNativePresentation(prompt, agent, exec.signal).catch(() => false) || stopped || !cover(agent)\n            || tools.get(definition.name, agent) !== registration(definition.name)) {\n            return failure('POLICY_DENIED', 'Native capability belongs to a different or inactive scope.')\n          }\n          return definition.execute(args, exec)\n        } }\n      })\n      const registration = (name: string) => definitions.find(definition => definition.name === name)\n      const dispose = registerNativeProviderAtScope(entry.ctx, scope, definitions,\n        tool => entry.ctx!.tools.register(tool), { inheritable: false, priority: 10 })\n      entry.disposers.push(dispose)\n      for (const definition of definitions) entry.owned.add(definition.name)\n    }\n    const cover = (agent: Agent): boolean => gate.allows(agent) && ownership.owns(agent)\n    const attach = (agent: Agent): void => {\n      if (stopped || entries.has(agent) || !agent?.ctx) return\n      const entry: Entry = { agent, runtime: new NativeFileTools({ ctx, config: { workerPath: worker, required: config.required, denyCredentialReads: config.denyCredentialReads } }),\n        owned: new Set(), disposers: [], ready: Promise.resolve() }\n      entries.set(agent, entry)\n      entry.fiber = agent.ctx.plugin({ inject: ['tools'], apply(scoped) { entry.ctx = scoped } })\n      entry.ready = Promise.resolve(entry.fiber).then(() => {\n        if (stopped || entries.get(agent) !== entry || !entry.ctx) return\n        return entry.runtime.start([]).then(async () => {\n          if (native.get(agent) === false || !await isNativePresentation(prompt, agent).catch(() => false)) return\n          if (stopped || entries.get(agent) !== entry || !cover(agent)) return\n          publish(agent, entry)\n        })\n      }).catch(error => ctx.logger.warn(`dsh-ops: ${mode} mode publication failed: ${String(error)}`))\n    }\n    const detach = (agent: Agent): void => {\n      const entry = entries.get(agent)\n      if (!entry) return\n      entries.delete(agent)\n      clear(entry)\n      void entry.fiber?.dispose()\n    }\n    const reconcile = (): void => {\n      if (stopped || mutating) return\n      mutating = true\n      try {\n        for (const [agent, entry] of entries) if (!cover(agent)) detach(agent)\n        for (const agent of ctx.get('agents')?.list?.() ?? []) if (cover(agent)) attach(agent)\n      } finally { mutating = false }\n    }\n    ctx.on('system-prompt/assemble', async (_assembly, context, next) => {\n      if (isPresentationProbe(context)) return next()\n      const agent = context.scope as Agent\n      await entries.get(agent)?.ready\n      const result = await next()\n      if (!agent || !gate.allows(agent)) return result\n      const allowed = !result.sections.some(section => section.name === 'tools:ptc-only' && section.text.trim())\n      if (native.get(agent) !== allowed) {\n        native.set(agent, allowed)\n        if (!allowed) detach(agent)\n        else attach(agent)\n        if (entries.has(agent)) await entries.get(agent)?.ready\n        return prompt.assemble(context)\n      }\n      return result\n    })\n    ctx.on('agent/created', ({ agent }) => { if (cover(agent)) attach(agent) })\n    ctx.on('agent/disposed', ({ agent }) => detach(agent))\n    ctx.on('session/event', (_session, event) => {\n      // A blank session may select another preset before its first turn; the mode\n      // that no longer matches must withdraw its surface.\n      if ((event as { type: string }).type === 'agent-preset/selected') reconcile()\n    })\n    if (gate.watch) ctx.effect(() => gate.watch!(reconcile), `dsh-ops: ${mode} publication observer`)\n    for (const agent of ctx.get('agents')?.list?.() ?? []) if (cover(agent)) attach(agent)\n    if (section !== null) {\n      const suffix = section\n      ctx.effect(() => prompt.section({\n        name: modeSectionName(suffix), order: MODE_SECTION_ORDERS[suffix] ?? 3250, interpolate: false,\n        text: context => {\n          const agent = context.agent\n          if (agent === undefined || !config.promptPolicy) return ''\n          const entry = entries.get(agent)\n          if (!entry || entry.owned.size === 0) return ''\n          const visible = new Set(visibleNames(tools, agent))\n          const published = [...entry.owned].filter(name => visible.has(name))\n          // The Windows shell replacement is published by the shared shell row;\n          // name it here when it is visible so routing text stays complete.\n          if (visible.has(BASH_TOOL)) published.push(BASH_TOOL)\n          return renderToolingPolicy({ published, shellComponent: true, extraGuidance: config.extraGuidance })\n        },\n      }), `dsh-ops: ${mode} tooling guidance`)\n    }\n    ctx.effect(() => () => {\n      stopped = true\n      for (const agent of [...entries.keys()]) detach(agent)\n      ownership.dispose()\n    }, `dsh-ops: ${mode} native lifecycle`)\n    ownership.refresh()\n  })\n}\n"
    },
    {
      "path": "src/official-tool-hiding.ts",
      "content": "/** Per-tool replacement through the host's scoped restriction and guard APIs.\n * Only explicit reviewed selections are masked. Missing selected counterparts\n * block the affected scope and restore its official tools until readiness returns.\n */\nimport type { Context } from './adapter/dsh/types.js'\nimport type { ToolGuard } from './adapter/dsh/types.js'\nimport type { OfficialReplacement } from './official-tool-catalog.js'\nimport { nativeProviders } from './publication/providers.js'\nimport { isPresentationProbe } from './publication/presentation.js'\nimport { resolveHidingConfig } from './config.js'\nexport { resolveHidingConfig } from './config.js'\nimport { OFFICIAL_REPLACEMENTS } from './official-tool-catalog.js'\nimport { safeDispose } from './teardown.js'\nimport { retired as retiredLegacyRow } from './settings/legacy.js'\n\ninterface Entry { context: Context; lifts: (() => void)[]; cleanupError?: string; error?: string; reported?: string\n  /** Set from the assembled surface: this scope presents one program entry, so its\n   * selected official names are not native duplicates and must stay dispatchable. */\n  collapsed?: boolean }\ninterface Plan { deny: string[]; failure?: string }\nconst message = (error: unknown): string => error instanceof Error ? error.message : String(error)\n\nexport const name = 'dsh-ops-hide-official'\n/** The host's reserved PTC transport: the only tool a collapsed scope may call. */\nconst RUN_CODE = 'run_code'\nconst blocked = (detail: string): string => `READINESS_BLOCKED (EXECUTOR_UNAVAILABLE): dsh-ops hide-official cannot verify selected replacements: ${detail}. Restore the selected OPS tools, remove the selection from replaceTools, or disable the dsh-ops-hide-official row.`\n\nexport function apply(root: Context, raw?: unknown): void {\n  if (retiredLegacyRow(root, 'hide-official')) return\n  const { replaceTools }: { replaceTools: OfficialReplacement[] } = resolveHidingConfig(raw)\n  // Empty and legacy-only rows install no hooks and cannot block a session.\n  if (!replaceTools.length) return\n  const selected = new Set<string>(replaceTools)\n  const hideable = (tool: string): boolean => selected.has(tool)\n  root.inject(['tools', 'systemPrompt'], ctx => {\n    const entries = new Map<object, Entry>()\n    let stopped = false, mutating = false\n    let lastSurface: string | undefined\n    const tools = ctx.get('tools')!\n    const apiError = (['schemas', 'get', 'restrict', 'guard'] as const).filter(api => typeof tools[api] !== 'function')\n    const fail = (message: string): void => ctx.logger?.error?.(message)\n    const clear = (entry: Entry): boolean => {\n      const pending = entry.lifts.splice(0)\n      const failed = []\n      for (const lift of pending) {\n        if (!safeDispose(lift, error => fail(`dsh-ops: restriction cleanup failed: ${message(error)}`), 'official-tool restriction')) failed.push(lift)\n      }\n      entry.lifts.push(...failed)\n      entry.cleanupError = failed.length > 0 ? 'host restriction cleanup failed; retrying before proceeding' : undefined\n      return failed.length === 0\n    }\n    // Readiness examines the unmasked scope. It never accepts ops_<same-name>\n    // as an equivalence claim, nor uses run_code as a native replacement.\n    const readiness = (agent: object): boolean[] => {\n      const owned = new Set(typeof tools.get === 'function' ? nativeProviders(ctx, agent).map(provider => provider.definition) : [])\n      return replaceTools.map(tool => {\n        const visible = typeof tools.get === 'function' ? tools.get(OFFICIAL_REPLACEMENTS[tool], agent) : undefined\n        return visible !== undefined && owned.has(visible)\n      })\n    }\n    const prepare = (agent: object, entry: Entry): Plan => {\n      const names = typeof tools.schemas === 'function' ? tools.schemas(agent).map(schema => schema.name) : []\n      const hidden = names.filter(hideable)\n      const ready = readiness(agent)\n      const missing = replaceTools.flatMap((tool, index) => {\n        const replacement = OFFICIAL_REPLACEMENTS[tool]\n        return names.includes(replacement) && ready[index]\n          ? [] : [`${tool} -> ${replacement}`]\n      })\n      const diagnostics = [\n        ...apiError.length ? [`missing host API: ${apiError.join(', ')}`] : [],\n        ...entry.cleanupError ? [entry.cleanupError] : [],\n        ...missing.length ? [`missing OPS surface: ${[...new Set(missing)].join(', ')}`] : [],\n      ]\n      const failure = diagnostics.length ? blocked(diagnostics.join('; ')) : undefined\n      // A failed plan hides nothing: no partial mask over an unready scope.\n      return { deny: failure ? [] : hidden, failure }\n    }\n    // Compare public surfaces before touching masks. Other components also\n    // reconcile tools/change; emitting a fresh restriction for an unchanged\n    // surface would otherwise cause a publication/withdrawal feedback loop.\n    // Schema bytes alone cannot detect a foreign tool shadowing an OPS definition.\n    const snapshot = (): string => JSON.stringify([tools.schemas(), ...[...entries.keys()].map(agent => [tools.schemas(agent), readiness(agent)])])\n    const reconcile = () => {\n      if (stopped || mutating) return\n      try { if (snapshot() === lastSurface) return } catch { /* reported by per-agent verification below */ }\n      mutating = true\n      try {\n        // Clear all masks first: inherited restrictions must not conceal a\n        // parent's missing capability while checking a child.\n        for (const entry of entries.values()) clear(entry)\n        const plans: [object, Entry, Plan][] = []\n        for (const [agent, entry] of entries) {\n          let plan: Plan\n          try { plan = prepare(agent, entry) }\n          catch (error) { plan = { deny: [], failure: blocked(message(error)) } }\n          plans.push([agent, entry, plan])\n        }\n        // Each scope owns its readiness and mask. A failed child is blocked at\n        // assembly/dispatch; it does not make a healthy ancestor or root fail.\n        for (const [agent, entry, plan] of plans) {\n          if (plan.failure) { clear(entry); entry.error = plan.failure; continue }\n          try {\n            // One restriction per complete plan; never partially hide when a\n            // single required replacement is absent.\n            if (plan.deny.length) entry.lifts.push(entry.context.tools.restrict({ deny: plan.deny }))\n            const leaked = tools.schemas(agent).map(schema => schema.name).filter(hideable)\n            if (leaked.length) throw new Error(`host scoped restriction cannot hide own-scope tools: ${leaked.join(', ')}`)\n            entry.error = undefined\n          } catch (error) { clear(entry); entry.error = blocked(message(error)) }\n        }\n        for (const entry of entries.values()) {\n          if (entry.error !== entry.reported) {\n            if (entry.error) fail(entry.error)\n            entry.reported = entry.error\n          }\n        }\n        try { lastSurface = snapshot() } catch { lastSurface = undefined }\n      } finally { mutating = false }\n    }\n    const block = (agent: object, detail: string): Error => {\n      const message = blocked(detail)\n      // Tool providers run before this waterfall, so keep the verified mask in\n      // place for the next request's schema collection. Only this assembly\n      // fails; invalidate readiness so transient provider errors are retryable.\n      const entry = entries.get(agent)\n      if (entry) entry.error = message\n      lastSurface = undefined\n      return new Error(message)\n    }\n    const attach = (agent: object): void => {\n      if (entries.has(agent) || !('ctx' in agent) || !agent.ctx || typeof agent.ctx !== 'object') return\n      entries.set(agent, { context: agent.ctx as Context, lifts: [], error: blocked('surface verification pending') })\n      reconcile()\n    }\n    const refusal: ToolGuard = exec => {\n      if (stopped) return blocked('component disposed')\n      if (!exec?.agent?.ctx) return blocked('calling agent scope unavailable')\n      attach(exec.agent)\n      reconcile() // Authority is live, not a startup snapshot.\n      const entry = entries.get(exec.agent)\n      // A collapsed (run_code) scope can never prove native readiness, so its error must\n      // not refuse the transport itself. The selected official names stay refused: the\n      // promise is that they never execute, in any presentation.\n      const transport = entry?.collapsed === true && exec.name === RUN_CODE\n      if (entry?.error && !transport) return entry.error\n      return hideable(exec.name)\n        ? blocked(`official tool ${exec.name} is selected for replacement`) : undefined\n    }\n    ctx.on('tools/pre-execute', async (exec, next) => {\n      const reason = refusal(exec)\n      return reason ? { kind: 'deny', reason, info: { name: 'ReadinessError', code: 'READINESS_BLOCKED' } } : next()\n    })\n    if (typeof tools.guard === 'function') ctx.effect(() => ctx.tools.guard(refusal), 'dsh-ops: replacement surface guard')\n    ctx.on('system-prompt/assemble', async (assembly, context, next) => {\n      // Only this package's exact, short-lived inspection context may pass before\n      // discovery publishes a selected replacement. Provider requests stay guarded.\n      if (!context.scope || isPresentationProbe(context)) return next()\n      attach(context.scope)\n      reconcile()\n      let result\n      try { result = await next() }\n      catch (error) { throw block(context.scope, `agent prompt assembly could not be verified: ${message(error)}`) }\n      reconcile()\n      const wire = Array.isArray(result?.tools) ? result.tools.map(schema => schema.name) : []\n      // A collapsed scope receives one program entry and nothing else: its selected\n      // official tools are not native duplicates there, and their OPS counterparts can\n      // only ever be SDK functions, so readiness is unprovable by construction. Fail\n      // closed on the assembled surface instead: a scope that really kept a selected\n      // official tool still throws, while a run_code scope owns no mask and no error.\n      // A host that transforms the presentation here attaches the tool array only after\n      // this waterfall, so the wire proves nothing then. The host also publishes the\n      // `tools:ptc-only` section for a real program presentation, renders it empty for a\n      // mixed one, and the section survives the deferred array — judge the scope by it\n      // rather than by the configuration view, which answers for `both` as well.\n      const ptcOnly = Array.isArray(result?.sections)\n        && result.sections.some(section => section.name === 'tools:ptc-only' && Boolean(section.text.trim()))\n      const collapsed = Array.isArray(result?.tools)\n        ? wire.length > 0 && wire.every(name => name === RUN_CODE)\n        : ptcOnly\n      const entry = entries.get(context.scope)\n      if (entry) entry.collapsed = collapsed\n      if (entry?.error) {\n        if (!collapsed) throw new Error(entry.error)\n        clear(entry); entry.error = undefined\n      }\n      // DSH 0.2.1 transforms a presentation here and attaches the tool array only\n      // after the waterfall, so the payload proves nothing about the assembled\n      // surface. Ask the scope view instead: an official tool this component\n      // selected is either still resolvable there or genuinely hidden. A host\n      // that still supplies schemas keeps the stricter assembled-surface check.\n      // A collapsed scope keeps the selected official names resolvable on purpose (the\n      // program calls their OPS counterparts) and owns no mask, so there is no assembled\n      // surface to leak there; the guard still refuses to dispatch them.\n      const leaked = collapsed ? []\n        : Array.isArray(result?.tools)\n          ? wire.filter(hideable)\n          : replaceTools.filter(tool => typeof tools.get === 'function' && tools.get(tool, context.scope) !== undefined)\n      if (leaked.length) throw block(context.scope, `assembled surface still contains hidden official tools: ${leaked.join(', ')}`)\n      return result\n    })\n    ctx.on('agent/created', ({ agent }) => { attach(agent); return undefined })\n    ctx.on('agent/disposed', ({ agent }) => {\n      const entry = entries.get(agent)\n      if (!entry) return\n      mutating = true\n      try { clear(entry); entries.delete(agent) } finally { mutating = false }\n      reconcile()\n    })\n    ctx.on('tools/change', reconcile)\n    ctx.effect(() => () => {\n      stopped = true; mutating = true\n      for (const entry of entries.values()) clear(entry)\n      entries.clear()\n    }, 'dsh-ops: selected official-tool restrictions')\n    for (const agent of ctx.get('agents')?.list?.() ?? []) attach(agent)\n    if (apiError.length) fail(blocked(`missing host API: ${apiError.join(', ')}`))\n  })\n}\n"
    },
