      "path": "src/execution/files.ts",
      "content": "/** Native file worker bridge. The host owns path resolution and DSH authority. */\nimport type { Context } from '../adapter/dsh/types.js'\nimport type { SubprocessRuntime } from '../adapter/dsh/types.js'\nimport type { SandboxPolicyService } from '../adapter/dsh/types.js'\nimport type { ToolRunContext } from '../adapter/dsh/types.js'\nimport type { FileSystem, FsTarget, FsInfo, FsObservation } from '../adapter/dsh/types.js'\nimport type { SandboxExecutionPolicy } from '../adapter/dsh/types.js'\nimport type { EffectState } from '../kernel/outcome.js'\nimport type { WorkerInvokeConfig } from './boundary.js'\nimport { record, errorText } from './boundary.js'\nimport { workerEnvelope } from './protocol.js'\nimport path from 'node:path'\nimport { credentialPath, credentialRefusal, credentialRoots } from '../credential-policy.js'\nimport { ensureSessionTemp, sessionTempDir } from '../session-temp.js'\nimport { denied, authorityChanged, normalizeNativeDenial, credentialDenied } from '../permissions.js'\nimport { inside, canonicalAnchor, anchoredPath, sessionAnchors } from '../authority-paths.js'\nimport { exchange } from './transport.js'\nimport { resolveWorker } from './runtime.js'\nimport { FILE_MUTATIONS } from '../policy.js'\nimport { normalizeArguments } from '../capabilities/arguments.js'\nimport { resolveReadFiles } from './read-files.js'\nimport { withCallBudget, CallBudgetError } from '../kernel/call-budget.js'\nimport { withResultSession } from '../kernel/result-lifecycle.js'\nimport { resultStorage } from '../kernel/result-storage.js'\nimport { resolveSessionDirectory } from '../adapter/dsh/working-directory.js'\n\nexport { resolveWorker }\n\nexport function failure(code: string, message: string, phase = 'preflight', effectState: EffectState = 'none') {\n  return { status: code === 'POLICY_DENIED' ? 'rejected' : 'error', phase,\n    changed: 0, matched: 0, skipped: 0, failed: 0, complete: false, omitted: 0,\n    error: { code, phase, retryable: false, effectState,\n      nextAction: effectState === 'none' ? 'Correct the request or restore host authority.' : 'Inspect the result; do not blindly retry after an unknown effect.', message } }\n}\n\nfunction absoluteTarget(raw: unknown, cwd: string): string | undefined {\n  if (typeof raw !== 'string' || raw.length === 0 || raw.includes('\\0')) return undefined\n  return path.isAbsolute(raw) ? path.normalize(raw) : path.resolve(cwd, raw)\n}\ntype Observation = { target: FsTarget; info: FsInfo | undefined }\n\n/** Host `fs` service, when the deployment has one; observation is skipped without it. */\nfunction hostFs(ctx: Context): FileSystem | undefined {\n  try {\n    const service = ctx.get('fs')\n    return typeof service?.resolve === 'function' && typeof service?.stat === 'function' ? service : undefined\n  } catch { return undefined }\n}\n\n/** Resolve and stat one path through the host provider, as host read does before reading. */\nasync function hostObservation(fsService: FileSystem | undefined, file: string, cwd: string, signal: AbortSignal): Promise<Observation | undefined> {\n  if (!fsService) return undefined\n  try {\n    const target = await fsService.resolve(file, { cwd, signal })\n    return { target, info: await fsService.stat(target, signal) }\n  } catch { return undefined }\n}\n\n/** Record an observation in the host's read-before-edit table; best effort, never fails the call. */\nfunction emitObserved(ctx: Context, observed: Observation | undefined, exec: ToolRunContext): void {\n  if (!observed) return\n  const { target, info } = observed\n  const observation: FsObservation | undefined = info === undefined ? { kind: 'absent' }\n    : info.type === 'file' && info.version ? { kind: 'present', version: info.version } : undefined\n  if (!observation) return\n  try { ctx.emit('fs/observed', target, observation, exec) } catch { /* the completed effect stands */ }\n}\n\n/** Refresh host observations for files a completed replace wrote (#17). */\nasync function observeReplaced(ctx: Context, fsService: FileSystem | undefined, value: Record<string, unknown>, cwd: string, exec: ToolRunContext, signal: AbortSignal): Promise<void> {\n  if (!fsService || value?.status !== 'completed' || value.dryRun || !(Number(value.changed) > 0) || !Array.isArray(value.items)) return\n  for (const item of value.items) {\n    if (!record(item) || typeof item.path !== 'string') continue\n    const observed = await hostObservation(fsService, item.path, cwd, signal)\n    // A size mismatch means another writer landed after our publish; leave the host to report stale.\n    if ((item.removed && observed && observed.info === undefined) || (observed?.info?.type === 'file' && observed.info.size === item.bytesAfter)) emitObserved(ctx, observed, exec)\n  }\n}\n\nexport async function invoke(ctx: Context, file: string, tool: string, args: unknown, exec: ToolRunContext, signal?: AbortSignal, config?: WorkerInvokeConfig): Promise<unknown> {\n  try {\n    const session = exec?.agent?.session\n    if (!session?.id) return failure('EXECUTOR_UNAVAILABLE', 'An authoritative session identity is required.')\n    return await withResultSession(ctx, session, signal, currentSignal =>\n      withCallBudget(ctx.root ?? ctx, String(session.id), currentSignal,\n        async () => {\n          const basis = await resolveSessionDirectory(ctx, exec.agent, currentSignal)\n          const value = await invokeTrusted(ctx, file, tool, args, exec, currentSignal, basis.cwd, config)\n          // Credential refusals deliberately disclose no absolute path, including ancestors.\n          if (record(value) && record(value.error) && value.error.code === 'CREDENTIAL_DENIED') return value\n          return { ...value as Record<string, unknown>, resolvedFrom: basis.cwd, cwdSource: basis.source }\n        }))\n  }\n  catch (error) {\n    if (error instanceof CallBudgetError) {\n      const value = failure(error.code, error.message)\n      value.error.nextAction = error.message\n      return value\n    }\n    return failure('EXECUTOR_UNAVAILABLE', 'DSH file authority or preparation is unavailable; no unrestricted fallback was attempted.')\n  }\n}\nasync function invokeTrusted(ctx: Context, file: string, tool: string, args: unknown, exec: ToolRunContext, signal: AbortSignal, cwd: string, config?: WorkerInvokeConfig): Promise<unknown> {\n  const session = exec?.agent?.session\n  if (!session?.id || typeof cwd !== 'string' || !path.isAbsolute(cwd)) return failure('EXECUTOR_UNAVAILABLE', 'An authoritative session identity and cwd are required.')\n  const policyService: SandboxPolicyService | undefined = ctx.get('sandboxPolicy')\n  const subprocess: SubprocessRuntime | undefined = ctx.get('subprocess')\n  if (!policyService?.resolve || !subprocess?.spawn) return failure('EXECUTOR_UNAVAILABLE', 'DSH policy and subprocess services are required.')\n  let policy: SandboxExecutionPolicy\n  try { policy = policyService.resolve({ session }) } catch { return failure('EXECUTOR_UNAVAILABLE', 'DSH policy resolution failed.') }\n  if (!['read-only', 'workspace-write', 'danger-full-access'].includes(policy?.mode)\n    || typeof policy.workspaceRoot !== 'string' || !path.isAbsolute(policy.workspaceRoot)) return failure('EXECUTOR_UNAVAILABLE', 'Invalid authoritative DSH policy.')\n\n  args = normalizeArguments(tool, args)\n  if (!record(args)) return failure('INVALID_ARGUMENT', 'Arguments must be an object.')\n  const mutates = (FILE_MUTATIONS as readonly string[]).includes(tool)\n  const reads = tool === 'read_files' ? resolveReadFiles(args, cwd) : undefined\n  if (reads && 'error' in reads) return failure('INVALID_ARGUMENT', reads.error)\n  const operationPath = absoluteTarget(args?.path ?? '.', cwd)\n  if (!operationPath) return failure('INVALID_ARGUMENT', 'path must be a non-empty path.')\n  // Credential locations are refused before the worker is spawned, so no read of one ever reaches a\n  // result. On by default; a row can turn the fence off for itself (report: credential fence).\n  if ((config?.denyCredentialReads ?? true) !== false) {\n    for (const target of reads ? reads.files.map(file => file.path) : [operationPath]) {\n      const verdict = credentialPath(target)\n      if (verdict.denied) {\n        const refusal = credentialRefusal(target, verdict.matched)\n        return credentialDenied(refusal.message)\n      }\n    }\n  }\n  const destination = ['copy', 'move'].includes(tool) ? absoluteTarget(args?.to, cwd) : undefined\n  if (['copy', 'move'].includes(tool) && !destination) return failure('INVALID_ARGUMENT', 'to must be a non-empty path.')\n  if (destination && (config?.denyCredentialReads ?? true) !== false) {\n    const verdict = credentialPath(destination)\n    if (verdict.denied) {\n      const refusal = credentialRefusal(destination, verdict.matched)\n      return credentialDenied(refusal.message)\n    }\n  }\n  // The temporary root is the session's OWN directory, not the shared system temp: the host sandbox\n  // grants `/tmp` to workspace-write on Linux, so endorsing the whole directory here would let one\n  // session replace another session's temporary files. The kernel still allows more than this fence\n  // does; the fence is deliberately the narrower of the two.\n  const privateTemp = sessionTempDir(session.id)\n  const anchors = sessionAnchors(policy, cwd)\n  const trustedPath = (value: string): string => anchoredPath(value, anchors)\n  const writeRoots = [canonicalAnchor(policy.workspaceRoot), trustedPath(privateTemp)]\n  const writeTargets = tool === 'copy' && destination ? [destination] : [operationPath, ...(destination ? [destination] : [])]\n  const requiredMode = (current: SandboxExecutionPolicy): 'workspace-write' | 'danger-full-access' => {\n    const roots = [canonicalAnchor(current.workspaceRoot), anchoredPath(privateTemp, sessionAnchors(current, cwd))]\n    return writeTargets.every(target => roots.some(root => inside(root, anchoredPath(target, sessionAnchors(current, cwd)))))\n      ? 'workspace-write' : 'danger-full-access'\n  }\n  if (mutates && policy.mode === 'read-only') return denied(policy, tool, requiredMode(policy), 'The user selected read-only; no files were changed.')\n  if (mutates && policy.mode === 'workspace-write') {\n    for (const target of writeTargets) {\n      const identity = trustedPath(target)\n      if (!writeRoots.some(root => inside(root, identity))) {\n        return denied(policy, `${tool} outside the workspace or this session's temporary directory`, 'danger-full-access', 'The user authorized workspace writes only; no files were changed.')\n      }\n      if (inside(writeRoots[1], identity)) {\n        const created = ensureSessionTemp(writeRoots[1])\n        if (!created.ok) return failure('EXECUTOR_UNAVAILABLE', created.message)\n      }\n    }\n  }\n\n  // Do NOT realpath the caller's parents here: that would erase a symlink/junction before\n  // the no-follow native traversal could reject it (especially on create-only writes).\n  const workerArgs = reads\n    ? { ...args, files: reads.files.map(file => ({ ...file, path: trustedPath(file.path) })) }\n    : { ...args, path: trustedPath(operationPath), ...(destination ? { to: trustedPath(destination) } : {}) }\n  // Traversals skip credential directories by identity, so a glob or grep cannot even name a private\n  // key that sits below one.\n  const denyRoots = (config?.denyCredentialReads ?? true) !== false ? credentialRoots() : []\n  const storage = await resultStorage(ctx, session, exec.agent, file, tool, policy, denyRoots,\n    (config?.denyCredentialReads ?? true) !== false, signal).catch(() => undefined)\n  const envelope = workerEnvelope('file', { root: trustedPath(cwd), scope: String(session.id), tool, args: workerArgs, read_only: policy.mode === 'read-only', deny_roots: denyRoots, deny_credential_names: (config?.denyCredentialReads ?? true) !== false, ...(policy.mode === 'workspace-write' ? { write_roots: writeRoots } : {}) }, config?.toolCallTimeoutMs, storage)\n  const input = JSON.stringify(envelope)\n  if (Buffer.byteLength(input) > 2 * 1024 * 1024) return failure('OUTPUT_LIMIT', 'Request exceeds the 2 MiB byte budget.')\n  let spawned = false\n  try {\n    // Trusted, fixed file operations follow DSH fs-sandbox's policy fence,\n    // not an arbitrary-code runner. The worker accepts data, never shell/code.\n    // This is the only file execution path, not a sandbox-failure fallback.\n    const argv = [file]\n    signal?.throwIfAborted?.()\n    const fsService = hostFs(ctx)\n    // Stat before reading, like host read: a concurrent change records the older version and fails stale later.\n    const readObservation = ['inspect_local_file', 'stat'].includes(tool) ? await hostObservation(fsService, operationPath, cwd, signal) : undefined\n    const readObservations = reads ? await Promise.all(reads.files.map(file => hostObservation(fsService, file.path, cwd, signal))) : []\n    signal?.throwIfAborted?.()\n    const current = policyService.resolve({ session })\n    if (current.mode !== policy.mode || current.workspaceRoot !== policy.workspaceRoot) {\n      if (!['read-only', 'workspace-write', 'danger-full-access'].includes(current?.mode) || !path.isAbsolute(current?.workspaceRoot ?? '')) return failure('EXECUTOR_UNAVAILABLE', 'Invalid authoritative DSH policy after preparation.')\n      const required = mutates ? requiredMode(current) : undefined\n      if (mutates && (current.mode === 'read-only' || (current.mode === 'workspace-write' && required === 'danger-full-access'))) return denied(current, tool, required, 'Authority changed during preparation; no files were changed.')\n      return authorityChanged(current, tool)\n    }\n    const result = await exchange(subprocess, { argv, cwd, stdio: { stdin: { data: input }, stdout: { maxBytes: envelope.budget.maxBytes }, stderr: { maxBytes: 16 * 1024 } }, graceMs: 1000, signal }, () => { spawned = true })\n    if (!result.readers) return failure('RESULT_UNKNOWN', 'Worker output readers are unavailable; inspect postconditions.', 'verify', 'unknown')\n    if (result.interrupted) return failure('RESULT_UNKNOWN', 'Worker interrupted; inspect postconditions.', 'execute', 'unknown')\n    if (result.lossy) return failure('OUTPUT_LIMIT', 'Worker output exceeded the byte budget; operation facts may have changed.', 'verify', 'unknown')\n    if (result.exitCode !== 0) return failure('RESULT_UNKNOWN', `Worker did not return a settled result: ${result.stderr.slice(0, 500)}`, 'execute', 'unknown')\n    if (result.invalid === 'json') return failure('RESULT_UNKNOWN', 'Worker returned invalid JSON; inspect postconditions.', 'verify', 'unknown')\n    if (!result.value) return failure('RESULT_UNKNOWN', 'Worker returned a non-object result; inspect postconditions.', 'verify', 'unknown')\n    const value = result.value\n    // Report reads/writes to the host's read-before-edit table, exactly like host read/edit. (#17)\n    if (['inspect_local_file', 'stat'].includes(tool) && value?.status === 'completed') emitObserved(ctx, readObservation, exec)\n    if (reads && Array.isArray(value?.items)) {\n      for (const [index, item] of value.items.entries()) {\n        if (record(item) && item.status === 'completed') emitObserved(ctx, readObservations[index], exec)\n      }\n    }\n    if (mutates) await observeReplaced(ctx, fsService, value, cwd, exec, signal)\n    const normalized = normalizeNativeDenial(value, policy, tool, mutates ? requiredMode(policy) : 'workspace-write')\n    return { ...normalized, sandbox: { mode: policy.mode, enforcement: 'policy', boundary: 'trusted-native-file-operations' } }\n  } catch (error) {\n    return failure(spawned ? 'RESULT_UNKNOWN' : 'EXECUTOR_UNAVAILABLE', `DSH trusted file executor failed; this is not a user authorization denial. ${errorText(error)}`, 'execute', spawned ? 'unknown' : 'none')\n  }\n}\n"
    },
    {
      "path": "src/execution/transport.ts",
      "content": "/** Bounded worker transport shared by fixed-file and confined execution policies. */\nimport type { SubprocessRuntime } from '../adapter/dsh/types.js'\nimport { record } from './boundary.js'\nexport interface WorkerExchange {\n  exitCode: number | null\n  interrupted: boolean\n  readers: boolean\n  lossy: boolean\n  stderr: string\n  value?: Record<string, unknown>\n  invalid?: 'json' | 'shape'\n}\nexport async function exchange(subprocess: SubprocessRuntime, spec: Parameters<SubprocessRuntime['spawn']>[0], started?: () => void): Promise<WorkerExchange> {\n  const handle = subprocess.spawn(spec)\n  started?.()\n  const outcome = await handle.done\n  const base = { exitCode: outcome.exitCode, interrupted: Boolean(spec.signal?.aborted || outcome.signal) }\n  if (!handle.collected.stdout || !handle.collected.stderr) return { ...base, readers: false, lossy: false, stderr: '' }\n  const stdout = handle.collected.stdout.readFrom(0), stderr = handle.collected.stderr.readFrom(0)\n  const result = { ...base, readers: true, lossy: Boolean(stdout.lossy), stderr: stderr.text }\n  if (base.interrupted || stdout.lossy || outcome.exitCode !== 0) return result\n  let value: unknown\n  try { value = JSON.parse(stdout.text) } catch { return { ...result, invalid: 'json' } }\n  return record(value) ? { ...result, value } : { ...result, invalid: 'shape' }\n}\n"
    },
    {
      "path": "src/execution/runtime.ts",
      "content": "/** Runtime discovery is installation-relative; explicit selections never silently fall back. */\nimport { createHash } from 'node:crypto'\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { fileURLToPath } from 'node:url'\nexport interface WorkerSelection { binaryPath?: string }\nexport interface RuntimeOptions { packageRoot?: string; env?: NodeJS.ProcessEnv; platform?: string; arch?: string }\nexport type WorkerResolution = { ok: true; file: string } | { ok: false; reason: string }\nexport const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')\nexport const PLATFORMS = Object.freeze(['win32-x64', 'linux-x64', 'darwin-arm64', 'darwin-x64'])\nexport function workerName(platform: string = process.platform) { return platform === 'win32' ? 'dsh-ops-worker.exe' : 'dsh-ops-worker' }\n/**\n * Read a JSON file, or name it.\n *\n * A missing receipt used to surface as a raw `ENOENT` out of `readFileSync`: it named\n * a path, but never said that the staged runtime was incomplete, which is the one\n * thing a caller has to know to fix it.\n *\n * Name the artifact **inside the package** (`runtime/<target>/provenance.json`), not the absolute\n * path, and report only the error's code or name: the raw `ENOENT`/`SyntaxError` message embeds the\n * operator's own install path, and an error text that reaches a tool result should not disclose it\n * (#30's point). The package-relative name keeps it actionable — you still know which artifact is\n * wrong.\n */\nfunction readJson(file: string, what: string, shown: string): Record<string, unknown> {\n  let text\n  try { text = fs.readFileSync(file, 'utf8') } catch (error) {\n    throw new Error(`Native worker ${what} at ${shown} could not be read (${(error as NodeJS.ErrnoException)?.code ?? (error as Error)?.name ?? 'unknown'})`)\n  }\n  try { return JSON.parse(text) as Record<string, unknown> } catch (error) {\n    throw new Error(`Native worker ${what} at ${shown} is not valid JSON (${(error as Error)?.name ?? 'unknown'})`)\n  }\n}\n/**\n * Resolve the worker without throwing, for a caller that has to *report* an\n * unresolvable host rather than fail on it — a test suite, whose convention for\n * \"this host cannot answer\" is `skipSuite` (exit 77) and never a crash while the\n * module is still loading.\n *\n * The support matrix is checked first, so an unsupported host gets the matrix's\n * own sentence and every other failure keeps the exact reason `resolveWorker`\n * would have thrown. `reason` is a complete clause a caller can put straight into\n * a skip message.\n *\n * @param {object} [config] - same as {@link resolveWorker}.\n * @param {object} [options] - same as {@link resolveWorker}.\n * @returns {{ok: true, file: string}|{ok: false, reason: string}} the attempt.\n */\nexport function tryResolveWorker(config: WorkerSelection = {}, options: RuntimeOptions = {}): WorkerResolution {\n  const platform = options.platform ?? process.platform\n  const arch = options.arch ?? process.arch\n  try {\n    if (!PLATFORMS.includes(`${platform}-${arch}`)) {\n      throw new Error(`this host is ${platform}-${arch}, outside the ${PLATFORMS.join(' / ')} support matrix`)\n    }\n    return { ok: true, file: resolveWorker(config, options) }\n  } catch (error) {\n    return { ok: false, reason: String((error as Error)?.message ?? error) }\n  }\n}\n\nexport function resolveWorker(config: WorkerSelection = {}, { packageRoot = PACKAGE_ROOT, env = process.env, platform = process.platform, arch = process.arch }: RuntimeOptions = {}): string {\n  if (!PLATFORMS.includes(`${platform}-${arch}`)) throw new Error(`dsh-ops supports Windows x64, Linux x64 and macOS (arm64/x64) only; unsupported runtime target ${platform}-${arch}.`)\n  const explicit = config.binaryPath ?? env.DSH_OPS_WORKER_BIN\n  const fromPackage = path.resolve(packageRoot, 'runtime', `${platform}-${arch}`, workerName(platform))\n  const fromSourceTree = path.resolve(packageRoot, 'native', 'target', 'release', workerName(platform))\n  const candidates = explicit !== undefined\n    ? [{ file: explicit, note: 'explicit selection (config.binaryPath / DSH_OPS_WORKER_BIN) — trusting the named path is the whole point of selecting it' }]\n    : [\n      { file: fromPackage, note: 'packaged runtime' },\n      { file: fromSourceTree, note: 'source-tree build (npm run build:ptc) — a dev artifact, with no receipt to verify against' },\n    ]\n  // Compare **resolved, case-folded** paths, never raw strings: Windows is\n  // case-insensitive, so `…\\RUNTIME\\…` names the same file as the candidate we\n  // derived — a substring/spelling test would let it skip verification entirely.\n  const same = (a: string, b: string) => (platform === 'win32' ? a.toLowerCase() === b.toLowerCase() : a === b)\n  const skipped: string[] = []\n  for (const { file, note } of candidates) {\n    if (!path.isAbsolute(file)) throw new Error('Native worker selection must be an absolute path.')\n    let stat\n    try { stat = fs.statSync(file) } catch (error) {\n      // Only \"no such file\" is an ordinary miss for a candidate list. A directory the\n      // process may not traverse, or a symlink that dangles, is a real condition that\n      // an \"unavailable\" message would hide behind the same words.\n      if ((error as NodeJS.ErrnoException).code !== 'ENOENT' && (error as NodeJS.ErrnoException).code !== 'ENOTDIR') throw new Error(`Native worker candidate ${file} could not be inspected: ${(error as Error).message}`)\n      skipped.push(`${file} (absent)`); continue\n    }\n    if (!stat.isFile()) { skipped.push(`${file} (not a regular file)`); continue }\n    // Windows has no execute bit, so this is POSIX-only. Without it, a worker copied\n    // over without its mode was accepted here and failed later as a bare `EACCES`\n    // from `spawn`, which reads as a sandbox problem rather than a missing `chmod`\n    // (report L12).\n    if (platform !== 'win32' && (stat.mode & 0o111) === 0) {\n      throw new Error(`Native worker ${file} is not executable (mode ${(stat.mode & 0o7777).toString(8).padStart(4, '0')}). Run chmod +x on it, or re-stage it with npm run build:ptc; dsh-ops never changes permissions on its own.`)\n    }\n    // Verify the packaged candidate against its receipt. Two limits, stated so nobody\n    // mistakes this for a trust boundary:\n    //   · the receipt sits **beside** the payload, so whoever replaces both passes.\n    //     This catches a build/metadata mismatch (a stale or mistaken runtime), not a\n    //     deliberate substitution — that needs npm's integrity or a signature, which is\n    //     outside this plugin.\n    //   · the selection test is \"is this the candidate we derived\", not a substring of a\n    //     path: `includes('\\runtime\\')` let any absolute path opt itself in (or out).\n    if (same(path.resolve(file), fromPackage)) {\n      const receipt = readJson(path.join(path.dirname(file), 'provenance.json'), 'provenance receipt',\n        path.posix.join('runtime', `${platform}-${arch}`, 'provenance.json'))\n      const version = readJson(path.join(packageRoot, 'package.json'), 'package manifest', 'package.json').version\n      if (receipt.target !== `${platform}-${arch}` || receipt.version !== version || receipt.executable !== workerName(platform)\n        || receipt.sha256 !== createHash('sha256').update(fs.readFileSync(file)).digest('hex')) throw new Error('Native worker provenance mismatch.')\n    } else {\n      // Not silent: an unverified worker binary is a fact the operator should see.\n      console.warn(`dsh-ops: native worker selected without provenance verification — ${note}: ${file}`)\n    }\n    return file\n  }\n  throw new Error(`Native worker unavailable for ${platform}-${arch}. Tried:\\n${skipped.map(entry => `  ${entry}`).join('\\n')}\\nInstall a runtime-bearing dsh-ops package, or run npm run build:ptc in the source checkout. No ACL repair, shell fallback or automatic download is performed.`)\n}\n"
    },
    {
      "path": "src/kernel/result-lifecycle.ts",
      "content": "import { randomUUID } from 'node:crypto'\nimport { CallBudgetError } from './call-budget.js'\n\nexport interface ResultSession { id: string; header?: { cwd?: string } }\nexport interface LifecycleHost {\n  root?: object\n  on(name: 'session/disposed', callback: (session: ResultSession) => void): unknown\n  on(name: 'session/event', callback: (session: ResultSession, event: { type: string }) => void): unknown\n  effect(callback: () => (() => Promise<void>), label: string): unknown\n  logger?: { warn?: (message: string) => void }\n}\ninterface LiveSession {\n  nonce: string\n  stopped: boolean\n  work: Map<AbortController, Promise<unknown>>\n  cleanup: Map<string, () => Promise<void>>\n  closing?: Promise<void>\n}\ninterface Owner { mounts: number; sessions: Map<ResultSession, LiveSession>; expired: WeakSet<ResultSession> }\nconst owners = new WeakMap<object, Owner>()\nfunction owner(ctx: Pick<LifecycleHost, 'root'>): Owner {\n  const key = ctx.root ?? ctx\n  let state = owners.get(key)\n  if (!state) { state = { mounts: 0, sessions: new Map(), expired: new WeakSet() }; owners.set(key, state) }\n  return state\n}\nfunction live(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession): LiveSession {\n  const state = owner(ctx)\n  if (state.expired.has(session)) throw new Error('Result session has expired')\n  // The pinned SessionStore emits its exact stored Session object throughout one lifetime.\n  if ([...state.sessions].some(([other, entry]) => other !== session && other.id === session.id && !entry.stopped)) {\n    throw new Error('Another live session owns this identity')\n  }\n  let entry = state.sessions.get(session)\n  if (!entry) {\n    entry = { nonce: randomUUID(), stopped: false, work: new Map(), cleanup: new Map() }\n    state.sessions.set(session, entry)\n  }\n  if (entry.stopped) throw new Error('Result session is closing')\n  return entry\n}\n/** A reopened persisted session receives a fresh authority binding, even with the same id. */\nexport function resultSessionNonce(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession): string {\n  return live(ctx, session).nonce\n}\nexport function registerResultCleanup(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession, key: string, cleanup: () => Promise<void>): void {\n  live(ctx, session).cleanup.set(key, cleanup)\n}\nexport async function withResultSession<T>(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession,\n  signal: AbortSignal | undefined, run: (signal: AbortSignal) => Promise<T>): Promise<T> {\n  const entry = live(ctx, session), controller = new AbortController()\n  const abort = () => controller.abort(signal?.reason)\n  if (signal?.aborted) abort(); else signal?.addEventListener('abort', abort, { once: true })\n  // Defer invocation so teardown always sees the promise before any worker can start.\n  const preceding = [...owner(ctx).sessions].filter(([other]) => other !== session && other.id === session.id)\n    .map(([, entry]) => entry.closing)\n  const work = Promise.resolve().then(async () => {\n    await Promise.allSettled(preceding)\n    if (controller.signal.aborted) throw new CallBudgetError('CANCELLED', 'OPS call cancelled before worker admission; no effects.')\n    return run(controller.signal)\n  })\n  entry.work.set(controller, work)\n  try { return await work }\n  finally { entry.work.delete(controller); signal?.removeEventListener('abort', abort) }\n}\nexport function expireResultSession(ctx: Pick<LifecycleHost, 'root' | 'logger'>, session: ResultSession, disposed = true): Promise<void> {\n  const state = owner(ctx), entry = state.sessions.get(session)\n  if (disposed) state.expired.add(session)\n  if (!entry) return Promise.resolve()\n  if (entry.closing) return entry.closing\n  entry.stopped = true\n  // Publish the barrier before abort listeners can synchronously reopen the same id.\n  entry.closing = Promise.resolve().then(async () => {\n    await Promise.allSettled(entry.work.values())\n    for (const cleanup of entry.cleanup.values()) {\n      try { await cleanup() }\n      catch { ctx.logger?.warn?.('dsh-ops: session result references expired; physical cache cleanup did not complete under current host authority. Temporary files remain for host or operator cleanup; no automatic retry is scheduled.') }\n    }\n    entry.cleanup.clear(); state.sessions.delete(session)\n  })\n  for (const controller of entry.work.keys()) controller.abort(new Error('Result session disposed'))\n  return entry.closing\n}\n/** Each component owns its listeners. Last-owner teardown expires remaining sessions. */\nexport function mountResultLifecycle(ctx: LifecycleHost): void {\n  const state = owner(ctx); state.mounts++\n  ctx.on('session/disposed', session => { void expireResultSession(ctx, session) })\n  ctx.on('session/event', (session, event) => {\n    if (event.type !== 'sandbox/mode') return\n    for (const [other, entry] of state.sessions) if (other === session) {\n      for (const controller of entry.work.keys()) controller.abort(new Error('Sandbox authority changed'))\n    }\n  })\n  ctx.effect(() => async () => {\n    if (--state.mounts !== 0) return\n    await Promise.allSettled([...state.sessions.keys()].map(session => expireResultSession(ctx, session, false)))\n  }, 'dsh-ops: session result lifecycle')\n}\n"
    },
    {
      "path": "src/projections/native/render.ts",
      "content": "import { Buffer } from 'node:buffer'\nimport { FILE_MUTATIONS } from '../../capabilities/registry.js'\nimport { compactRanges } from './ranges.js'\nimport { encodeSourceLine } from './line-encoding.js'\nimport { renderDocument } from './documents.js'\nimport { isDocumentTool } from '../../capabilities/documents.js'\nimport { renderResult } from './result-render.js'\nimport { errorPolicy } from '../../kernel/errors.js'\nimport type { EffectState } from '../../kernel/outcome.js'\n\nexport const NATIVE_OUTPUT_BYTES = 64 * 1024\n\ntype Row = Record<string, unknown>\nconst record = (value: unknown): value is Row => value !== null && typeof value === 'object' && !Array.isArray(value)\nconst rows = (value: unknown): Row[] => Array.isArray(value) ? value.filter(record) : []\nconst count = (value: unknown): value is number => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0\nconst label = (value: unknown): string => String(value ?? '').replace(/[\\r\\n\\t\\x00-\\x1f\\x7f]/g, char => JSON.stringify(char).slice(1, -1))\n// Keep physical line labels intact without confusing literal backslashes with escapes.\nconst contentLine = (value: unknown): string => encodeSourceLine(String(value ?? ''))\nconst field = (value: unknown): string => typeof value === 'string' ? label(value) : JSON.stringify(value)\nconst encodedBytes = (text: string): number => Buffer.byteLength(JSON.stringify([{ type: 'text', text }]), 'utf8')\n\n/** Bound the final escaped content blocks, not the unescaped source text. */\nexport function capNativeText(text: string, maxBytes = NATIVE_OUTPUT_BYTES, recovery = 'Re-read the original range with a smaller limit; do not advance past undisplayed content.'): string {\n  if (!Number.isSafeInteger(maxBytes) || maxBytes < 512 || maxBytes > NATIVE_OUTPUT_BYTES) {\n    throw new RangeError('Native output budget must be 512-65536 bytes')\n  }\n  if (encodedBytes(text) <= maxBytes) return text\n  const notice = `\\n[Notice: Display incomplete. TruncatedBy: output-budget. ${recovery}]`\n  let low = 0\n  let high = text.length\n  while (low < high) {\n    const middle = Math.ceil((low + high) / 2)\n    if (encodedBytes(text.slice(0, middle) + notice) <= maxBytes) low = middle\n    else high = middle - 1\n  }\n  // Do not emit half of an astral Unicode character when the budget lands inside a pair.\n  if (low > 0 && /[\\uD800-\\uDBFF]/u.test(text[low - 1]!)) low--\n  return text.slice(0, low) + notice\n}\n\nfunction facts(value: Row, keys: string[]): string {\n  return keys.filter(key => value[key] !== undefined).map(key => `${key}=${field(value[key])}`).join('; ')\n}\nfunction notices(value: Row, displayed: number): string[] {\n  const incomplete = value.complete === false || value.truncated === true || value.status === 'partial'\n  const details = [\n    `${displayed} item${displayed === 1 ? '' : 's'} displayed`,\n    `complete=${value.complete === undefined ? (incomplete ? 'false' : 'unspecified') : value.complete}`,\n    `TruncatedBy: ${value.truncatedBy ?? (incomplete ? 'worker-limit' : 'none')}`,\n    facts(value, ['nextOffset', 'nextIndex', 'pending', 'omitted', 'total', 'matched', 'files', 'matches', 'skippedFiles', 'skippedPaths', 'failed', 'continuation']),\n  ].filter(Boolean)\n  const output = [`[Notice: ${details.join('; ')}.]`]\n  for (const item of rows(value.items)) {\n    if (item.truncatedInLine === true) {\n      output.push(`[Notice: Line ${label(item.line)} in ${label(item.path)} is incomplete; ${facts(item, ['bytesTotal', 'bytesOmitted'])}. Use a smaller or binary range; the next line offset does not recover its missing suffix.]`)\n    }\n    if (item.metadataWarnings !== undefined) output.push(`[Notice: ${label(item.path)} metadataWarnings=${field(item.metadataWarnings)}.]`)\n  }\n  return output\n}\n\nfunction inspect(args: Row, value: Row): string[] {\n  const items = rows(value.items)\n  const output: string[] = []\n  const groups = new Map<string, Row[]>()\n  for (const item of items) {\n    const path = typeof item.path === 'string' ? item.path : String(args.path ?? value.path ?? '(path unavailable)')\n    const group = groups.get(path) ?? []\n    group.push(item)\n    groups.set(path, group)\n  }\n  if (groups.size === 0) groups.set(String(args.path ?? value.path ?? '(path unavailable)'), [])\n  for (const [path, group] of groups) {\n    const hex = group.some(item => item.view === 'hex') || args.view === 'hex'\n    const numbers = group.map(item => item.line).filter(count)\n    const span = numbers.length ? `${numbers[0]}-${numbers.at(-1)}` : 'none'\n    const total = count(value.lineCount) ? value.lineCount : count(value.total) ? value.total : '?'\n    output.push(`=== FILE: ${label(path)} (${hex ? 'Hex' : `Lines ${span} of ${total}`}) ===`)\n    const observed = facts(value, ['revision', 'bytes', 'lineCount'])\n    if (observed) output.push(`[Notice: ${observed}.]`)\n    for (const item of group) {\n      if (hex) output.push(`${label(item.offset ?? '?')} | ${contentLine(item.text)}`)\n      else output.push(`${count(item.line) ? item.line : '?'} | ${contentLine(item.text)}`)\n    }\n    if (!group.length) output.push(value.lineCount === 0 ? '(empty file)' : '(no lines in this range)')\n  }\n  output.push(...notices(value, items.length))\n  return output\n}\n\nfunction failure(value: Row): string[] {\n  const error = record(value.error) ? value.error : {}\n  const code = typeof error.code === 'string' ? error.code : 'UNKNOWN_ERROR'\n  const effect = ['none', 'applied', 'partial', 'unknown'].includes(String(error.effectState))\n    ? error.effectState as EffectState : 'unknown'\n  const advice = errorPolicy(code, effect)\n  const status = value.status === 'rejected' && effect === 'none' ? 'rejected' : advice.status\n  const output = [`${status}: ${label(code)}`,\n    `[Notice: effectState=${effect}; retry=${advice.retry}; ${facts(error, ['phase', 'reason'])}.]`]\n  if (typeof error.nextAction === 'string') output.push(`Next: ${label(error.nextAction)}`)\n  if (error.message) output.push(label(error.message))\n  if (rows(value.items).length) output.push('Partial receipts:', ...receiptItems(value))\n  return output\n}\n\nconst mutations = new Set<string>(FILE_MUTATIONS)\nfunction receiptItems(value: Row): string[] {\n  return rows(value.items).map(item => `${label(item.path ?? '(path unavailable)')}: ${facts(item, [\n    'removed', 'changed', 'revision', 'revisionBefore', 'revisionAfter', 'bytes', 'bytesBefore', 'bytesAfter',\n    'lineCountBefore', 'lineCount', 'replacements', 'metadata', 'metadataWarnings',\n  ])}`)\n}\nfunction receipts(tool: string, value: Row): string[] {\n  const output = [`${label(tool)}: ${value.dryRun === true ? 'preview' : label(value.status ?? 'unknown')}; ${facts(value, ['changed', 'matched', 'skipped', 'failed', 'revisionBefore'])}`,\n    ...receiptItems(value)]\n  output.push(...notices(value, rows(value.items).length))\n  return output\n}\nfunction stat(args: Row, value: Row): string[] {\n  return [`${label(value.path ?? args.path ?? '(path unavailable)')}: ${facts(value, [\n    'exists', 'revision', 'bytes', 'lineCount', 'readonly', 'modifiedMs', 'mode',\n  ])}`, ...notices(value, rows(value.items).length)]\n}\nfunction diff(args: Row, value: Row): string[] {\n  const output = [`=== DIFF: ${label(args.path ?? value.path ?? '(path unavailable)')} ===`]\n  for (const key of ['before', 'after', 'hunk']) {\n    if (record(value[key])) output.push(`[Notice: ${key}: ${facts(value[key], Object.keys(value[key]))}.]`)\n  }\n  for (const item of rows(value.items)) {\n    const sign = item.kind === 'remove' ? '-' : item.kind === 'add' ? '+' : '?'\n    output.push(`${sign} ${label(item.line ?? '?')} | ${contentLine(String(item.text ?? '').replace(/\\r?\\n$/, ''))}`)\n  }\n  output.push(...notices(value, rows(value.items).length))\n  return output\n}\n\nfunction listing(tool: string, args: Row, value: Row): string[] {\n  const output: string[] = []\n  if (value.scanComplete !== undefined) output.push(`[Notice: ${facts(value, ['scanComplete', 'pageComplete', 'scannedFiles', 'skippedFiles', 'skipReasons', 'matchedObserved', 'matchedTotal'])}.]`)\n  if (typeof value.nextAction === 'string') output.push(`Next: ${label(value.nextAction)}`)\n  const items = Array.isArray(value.items) ? value.items : []\n  for (const item of items) {\n    if (typeof item === 'string') { output.push(label(item)); continue }\n    if (!record(item)) continue\n    const path = label(item.path ?? '(path unavailable)')\n    if (tool === 'grep' && typeof item.text === 'string') {\n      const numbered = count(item.line) && item.line > 0\n      const start = numbered ? Math.max(1, Number(item.line) - (count(args.beforeContext) ? args.beforeContext : 0)) : 0\n      if (numbered && start !== item.line) output.push(`[Notice: Match starts at ${path}:${item.line}; context follows.]`)\n      for (const [index, line] of item.text.split('\\n').entries()) output.push(`${path}${numbered ? `:${start + index}` : ''} | ${contentLine(line)}`)\n    } else {\n      const rest = { ...item }\n      delete rest.path\n      output.push(`${path}${Object.keys(rest).length ? `: ${facts(rest, Object.keys(rest))}` : ''}`)\n    }\n  }\n  const summary = facts(value, ['exists', 'revision', 'bytes', 'lineCount', 'metadata', 'revisionBefore', 'revisionAfter', 'changed', 'dryRun'])\n  if (summary) output.unshift(summary)\n  output.push(...notices(value, items.length))\n  return output\n}\n\n/** Native presentation is independent of the canonical execution value returned to PTC. */\nexport function renderNative(tool: string, args: unknown, result: unknown): string {\n  if (!record(result)) return capNativeText('[Notice: No structured result was returned.]')\n  const input = record(args) ? args : {}\n  let lines: string[]\n  if (isDocumentTool(tool)) lines = renderDocument(tool, input, result)\n  else if (record(result.error) || ['error', 'rejected', 'conflict', 'unknown', 'failed'].includes(String(result.status))) lines = failure(result)\n  else if (tool === 'result') return capNativeText(renderResult(input, result), NATIVE_OUTPUT_BYTES, 'Repeat the same offset with smaller limit/maxBytes; do not advance past undisplayed rows.')\n  else if (tool === 'read_files') lines = compactRanges(input, result) ?? readMany(result)\n  else if (tool === 'inspect_local_file') lines = inspect(input, result)\n  else if (mutations.has(tool)) lines = receipts(tool, result)\n  else if (tool === 'stat') lines = stat(input, result)\n  else if (tool === 'diff') lines = diff(input, result)\n  else lines = listing(tool, input, result)\n  // Keep the locator ahead of potentially clipped model text so its omitted suffix stays recoverable.\n  if (record(result.reference)) lines.unshift('[Stored reference: ' + facts(result.reference, ['refId', 'producerTool', 'totalItems', 'totalBytes'])\n    + '; referenceRoot=' + field(result.referenceRoot) + '. Page with ops_result; inspect source capture/coverage facts before claiming completeness.]')\n  if (record(result.storageError)) lines.unshift('[Storage: ' + facts(result.storageError, ['code', 'message', 'effectState']) + '. Cache effects are separate from business effects.]')\n  if (typeof result.resolvedFrom === 'string') lines.unshift('[cwd: ' + facts(result, ['resolvedFrom', 'cwdSource']) + '.]')\n  return capNativeText(lines.join('\\n'), NATIVE_OUTPUT_BYTES, mutations.has(tool)\n    ? 'Inspect current state before another mutation; do not repeat the write to recover undisplayed receipts.'\n    : isDocumentTool(tool) ? 'Use the stored reference when available; otherwise repeat this range with a smaller limit or use a dedicated reader for a large record. Do not advance past undisplayed content.' : undefined)\n}\n\nfunction readMany(value: Row): string[] {\n  const output: string[] = []\n  for (const item of rows(value.items)) {\n    if (record(item.error)) output.push(`=== FILE: ${label(item.path)} ===`, ...failure(item))\n    else output.push(...inspect(item, item))\n  }\n  output.push(...notices(value, rows(value.items).length))\n  return output\n}\n"
    },
    {
      "path": "src/projections/native/ranges.ts",
      "content": "import path from 'node:path'\nimport { encodeSourceLine } from './line-encoding.js'\ntype Row = Record<string, unknown>\nconst record = (value: unknown): value is Row => value !== null && typeof value === 'object' && !Array.isArray(value)\nconst integer = (value: unknown): value is number => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0\nconst quoted = (value: string): string => JSON.stringify(value).replace(/[\\u0085\\u2028\\u2029]/g, char => `\\\\u${char.charCodeAt(0).toString(16).padStart(4, '0')}`)\ninterface Range { path: string; revision: string; total: number; next: number; complete: boolean; lines: { line: number; text: string }[] }\n/** Compact only a fully evidenced requested range. Physical gaps keep the general diagnostic renderer. */\nfunction range(input: unknown, value: unknown): Range | undefined {\n  if (!record(input) || !record(value) || value.status !== 'completed' || value.error || value.reference || value.storageError\n    || value.truncated !== false || value.truncatedBy !== undefined || value.nextAction !== undefined\n    || value.metadataWarnings !== undefined || value.failed !== 0 || !integer(value.lineCount)\n    || !integer(value.nextOffset) || typeof value.path !== 'string' || !path.isAbsolute(value.path)\n    || typeof value.revision !== 'string' || !/^[a-f0-9]{64}$/.test(value.revision) || !Array.isArray(value.items)) return\n  const offset = input.offset ?? 1, limit = input.limit ?? 200\n  if (!integer(offset) || offset < 1 || !integer(limit) || limit < 1) return\n  const expected = Math.max(0, Math.min(limit, value.lineCount - offset + 1))\n  if (value.items.length !== expected || value.nextOffset !== offset + expected\n    || value.complete !== (offset - 1 + expected >= value.lineCount)) return\n  const lines: Range['lines'] = []\n  for (const [index, item] of value.items.entries()) {\n    if (!record(item) || item.line !== offset + index || item.path !== value.path || typeof item.text !== 'string'\n      || item.view === 'hex' || item.truncatedInLine === true || item.metadataWarnings !== undefined) return\n    lines.push({ line: offset + index, text: item.text })\n  }\n  return { path: value.path, revision: value.revision, total: value.lineCount, next: value.nextOffset, complete: value.complete, lines }\n}\n/** Canonical metadata remains unchanged; Native needs one revision and one clear continuation per file. */\nexport function compactRanges(input: Row, value: Row): string[] | undefined {\n  if (!Array.isArray(input.files) || !Array.isArray(value.items) || !input.files.length || input.files.length !== value.items.length\n    || value.reference || value.storageError || value.truncated !== false || value.failed !== 0 || value.pending !== 0\n    || value.total !== input.files.length || value.nextIndex !== input.files.length) return\n  const observed: Range[] = []\n  for (const [index, item] of value.items.entries()) {\n    const current = range(input.files[index], item)\n    if (!current) return\n    observed.push(current)\n  }\n  const parent = path.dirname(observed[0]!.path)\n  const base = observed.length > 1 && observed.every(item => path.dirname(item.path) === parent) ? parent : undefined\n  const output = base ? [`[Base: ${quoted(base)}]`] : []\n  for (const item of observed) {\n    const span = item.lines.length ? `${item.lines[0]!.line}-${item.lines.at(-1)!.line}` : 'none'\n    output.push(`=== FILE: ${quoted(base ? path.basename(item.path) : item.path)} (Lines ${span} of ${item.total}) ===`)\n    for (const line of item.lines) output.push(`${line.line}|${encodeSourceLine(line.text)}`)\n    if (!item.lines.length) output.push(item.total === 0 ? '(empty file)' : '(no lines in this range)')\n    output.push(`[revision=${item.revision}; ${item.complete ? 'end of file; complete=true' : `more lines; nextOffset=${item.next}`}]`)\n  }\n  output.push(`[Notice: ${observed.length}/${input.files.length} requested ranges returned.]`)\n  return output\n}\n"
